package android.os; public final class Looper {private static final Thread MAIN_THREAD=Thread.currentThread();private static final Looper MAIN=new Looper();private static final ThreadLocal<Looper> CURRENT=new ThreadLocal<>();private Looper(){} public static Looper getMainLooper(){return MAIN;}public static Looper myLooper(){Looper value=CURRENT.get();return value!=null?value:Thread.currentThread()==MAIN_THREAD?MAIN:null;}public static void hostSetMain(boolean main){if(main)CURRENT.set(MAIN);else CURRENT.set(new Looper());}public static void hostReset(){CURRENT.remove();}}
